            diag: [{ p: '눕어요', note: '눕다 is ㅂ-irregular (Lesson 11): ㅂ → 우 → 누워요.' }, { p: '누와요', note: '와 is only for 돕다: 누워요.' }, { p: '누어요', note: 'The ㅂ turns into 우, it doesn’t just vanish: 누워요.' }],
