      cctv: [
        { id: 'B.c1', type: 'write', prompt: '“I’m going to the bookstore, too. Let’s go together!”', ko: '저도 서점에 갈 거예요. ___', ans: ['같이 가요!'], soft: [{ p: '(저도 서점에 갈 거예요 |)(우리 |)같이 가요', note: 'Accepted.' }], skill: 'l16.form', diag: [{ p: '같이 가자', note: '-자 is informal. Polite: 같이 가요!' }, { p: '같이 갑시다', note: 'The book: use -아/어/여요, not -(으)ㅂ시다.' }], explain: 'Textbook exercise 4.', en: 'I’m going to the bookstore, too. Let’s go together!' },
        { id: 'B.c2', type: 'write', prompt: '“Aren’t you hungry? Let’s eat hamburgers.”', ko: '배 안 고파요? ___', ans: ['우리 햄버거 먹어요.'], soft: [{ p: '(배 안 고파요 |)(우리 |)(같이 |)햄버거(를|) (같이 |)먹어요', note: 'Accepted.' }], skill: 'l16.form', diag: [{ p: '(우리 |)햄버거(를|) 먹으세요', note: 'Please eat (you) ≠ let’s eat: 먹어요.' }, { p: '(우리 |)햄버거(를|) 먹자', note: '-자 is informal. Polite: 먹어요.' }], explain: 'Textbook exercise 5.', en: 'Aren’t you hungry? Let’s eat hamburgers.' },
        { id: 'B.c3', type: 'write', prompt: 'Write in Korean: “Let’s go somewhere else. I think this place is not so good.”', ans: ['다른 데 가요. 여기 안 좋은 것 같아요.'], soft: [{ p: '다른 (데|곳에|곳으로|데로) 가요 여기(는|) 안 좋은 것 같아요', note: 'Accepted.' }], skill: 'l16.form', diag: [{ p: '다른 데 가요 여기(는|) 안 좋는 것 같아요', note: '좋다 is descriptive: 좋은 것 같아요 (Lesson 9).' }, { p: '다른 데 가세요 여기(는|) 안 좋은 것 같아요', note: '가세요 = please go (you). Let’s go: 가요.' }], explain: 'Textbook sample sentence.', en: 'Let’s go somewhere else. I think this place is not so good.' },
        { id: 'B.c4', type: 'write', prompt: 'Write in Korean: “Let’s exercise together from tomorrow.”', ans: ['우리 내일부터 같이 운동해요.'], soft: [{ p: '(우리 |)내일부터 같이 운동(을 |)해요', note: 'Accepted.' }], skill: 'l16.form', diag: [{ p: '(우리 |)내일부터 같이 운동할 거예요', note: 'A plan (we will). Let’s: 운동해요.' }], explain: 'Workbook dictation 17.', en: 'Let’s exercise together from tomorrow.' },
        { id: 'B.c5', type: 'fill', prompt: '눕다 + -(으)시죠 (honorific “let’s”)', ko: '___.', ans: ['누우시죠'], units: ['누', '우', '시', '죠'], extra: ['눕', '으', '조'], skill: 'l16.irr', diag: [{ p: '눕으시죠', note: '-으시죠 starts with a vowel: ㅂ → 우 → 누우시죠.' }, { p: '누시죠', note: 'ㅂ becomes 우: 누우시죠.' }], explain: 'Workbook 10: 누우시죠.', en: '' },
        { id: 'B.c6', type: 'write', prompt: 'Write in Korean: “Let’s start on Saturday. What do you think?”', ans: ['토요일에 시작해요. 어때요?'], soft: [{ p: '토요일에 시작해요 어때요', note: 'Accepted.' }, { p: '토요일에 시작할래요', note: 'Accepted: shall we start on Saturday? (polite/casual).' }], skill: 'l16.form', diag: [{ p: '토요일에 시작했어요 어때요', note: 'That is the past. Let’s start: 시작해요.' }, { p: '토요일에 시작하요 어때요', note: '하 + 여요 = 해요: 시작해요.' }], explain: 'Textbook sample sentence.', en: 'Let’s start on Saturday. What do you think?' },
      ],
