            diag: [{ p: '(할머니 |)같이 (기다리어요|기다리요|기달려요)', note: '기다리 + 어요 contracts: 기다려요.' }, { p: '(할머니 |)같이 기다리세요', note: '기다리세요 = please wait (you). Let’s wait: 기다려요.' }, { p: '(할머니 |)같이 기다리자', note: '-자 is informal — not to Grandma. 기다려요.' }],
