MM.mnemo[16] = {"cards":[{"id":"ko-k3-0289","w":"들다","cs":"zvednout; nést; držet (v ruce)","en":"to lift","p":"v","o":"k","ex":"이거 너무 무거워요. 같이 들어요.","exc":"Tohle je moc těžké. Zvedněme to společně.","h":"TŮL ≈ TULEŇ: tuleň zvedá a nese míč na čumáku. 들어요.","m":"Nepravidelné časování ㄹ: před ㄴ, ㅂ, ㅅ vypadává ㄹ (např. 드세요 = zvedněte / vezměte si). Má i další významy, např. ‚vejít‘ nebo ‚stát (peníze/čas)‘.","tv":["들어요"],"irr":"ㄹ (odpadá)"},{"id":"ko-k3-0290","w":"같이","cs":"spolu; společně; dohromady","en":"together","p":"o","o":"k","ex":"같이 가요!","exc":"Pojďme spolu!","h":"KA-ČI ≈ KAČKY: kačky plavou spolu.","m":"Výslovnost [가치] (před 이 se ㅌ měkčí na ㅊ). Synonymum 함께 (společně)."},{"id":"ko-k3-0291","w":"햄버거","cs":"hamburger","en":"hamburger","p":"n","o":"e","ex":"배 안 고파요? 우리 햄버거 먹어요.","exc":"Nemáš hlad? Dejme si hamburger.","h":"Z angličtiny hamburger.","m":"Výpůjčka z anglického hamburger. V Koreji se zkracuje i na 버거 (např. 치즈버거 = cheeseburger, 불고기버거 = bulgogi burger)."},{"id":"ko-k3-0292","w":"다른 데","cs":"jinam; jiné místo","en":"somewhere else","p":"f","o":"k","ex":"다른 데 가요. 여기 안 좋은 것 같아요.","exc":"Pojďme jinam. Zdá se, že tohle místo není moc dobré. (-은 것 같다 → zdá se, že)","h":"다른 = jiný (TA-RŮN ≈ TARZAN skáče jinam) + 데 = místo.","m":"Složené z 다른 (jiný, přívlastkový tvar od 다르다) + 데 (místo). Stejně funguje 좋은 데 (dobré místo) nebo 이런 데 (takové místo)."},{"id":"ko-k3-0295","w":"잠깐","cs":"chvilku; na okamžik; moment","en":"for a moment","p":"o","o":"k","ex":"좋아요. 그럼 잠깐 나갈까요?","exc":"Dobře. Půjdeme tedy na chvilku ven? (-ㄹ까요 → máme udělat?)","h":"ČAM-KAN ≈ ŠAMPAŇ: počkej chvilku, otevřu šampaňské.","m":"Často se používá ve frázi 잠깐만요! (Moment! / Chviličku počkejte!). Synonymum 잠시."},{"id":"ko-k3-0296","w":"무겁다","cs":"těžký (hmotností)","en":"to be heavy","p":"a","o":"k","ex":"이거 너무 무거워요.","exc":"Tohle je moc těžké.","h":"MU-GOP ≈ MULA: mula nese těžký náklad. 무거워요.","m":"Nepravidelné časování ㅂ → 무거워요, před podstatným jménem 무거운. Používá se pro váhu (opak 가볍다 = lehký); ‚těžký, obtížný‘ je 어렵다.","tv":["무거워요","무거웠어요"],"irr":"ㅂ"},{"id":"ko-k3-0297","w":"내일부터","cs":"od zítřka","en":"from tomorrow","p":"o","o":"m","ex":"우리 내일부터 같이 운동해요.","exc":"Pojďme od zítřka cvičit spolu. (부터 → od)","h":"내일 = zítra („NE, ILONO, až zítra“) + 부터 = od (PU-TO ≈ PUTOVAT od…).","m":"Složené z 내일 (zítra: 來 příští + 日 den) + částice 부터 (od). Částice 부터 označuje začátek v čase nebo pořadí (pro místo se používá 에서).","r":["rae-來","il-日"]},{"id":"ko-k3-0298","w":"어때요?","cs":"Jaké to je?; Co na to říkáš?","en":"how is it? what do you think?","p":"f","o":"k","ex":"토요일에 시작해요. 어때요?","exc":"Začněme v sobotu. Co na to říkáš? (에 → kdy)","h":"O-TE-JO ≈ „OTO, JO?“: „Co na to říkáš, Oto?“","m":"Zdvořilý tvar přídavného jména 어떻다 (jaký) vzniklý nepravidelným časováním ㅎ. Používá se při návrzích nebo dotazu na názor (‚Co říkáš na…? / Jaké to je?‘)."}],"gram":{"id":"ko-k3-g16","w":"-아/어/여요 (청유형)","en":"Let’s","cs":"pojďme…, …me (výzva ke společné činnosti)","vy":"Běžný zdvořilý přítomný čas slovesa na -아/어/여요 funguje v korejštině i jako přátelská výzva ke společné činnosti (‚pojďme…, dejme si…, sejděme se…‘). Konkrétní význam se pozná z kontextu, časového údaje nebo slov jako 같이 (spolu) a 우리 (my). Ve formálnějších situacích se používá zdvořilejší -(으)시죠, mezi blízkými přáteli neformální -자 a jako zdvořilý dotaz -(으)ㄹ래요?.","m":"Tvar -아/어/여요 má v korejštině tři tváře podle intonace a kontextu: oznamovací větu (‚jíme‘), otázku (‚jíš?‘) i výzvu (‚pojďme jíst‘). Když chceš návrh zjemnit otázkou, použij -(으)ㄹ까요? nebo -(으)ㄹ래요?.","s":[["시작해요. · 시작하시죠. · 시작하자.","Začněme. (běžný zdvořilý · uctivý · neformální tvar)"],["시작할래요? · 시작하실래요?","Začneme? / Nezačneme? (zdvořilý hovorový · uctivější tvar)"],["저도 서점에 갈 거예요. 같이 가요!","Já jdu taky do knihkupectví. Pojďme spolu!"],["배 안 고파요? 우리 햄버거 먹어요.","Nemáš hlad? Pojďme si dát hamburger."],["지금 두 시예요. 세 시에 여기에서 만나요.","Teď jsou dvě hodiny. Sejděme se tady ve tři."],["저 금요일까지 바빠요. 토요일에 시작해요. 어때요?","Do pátku mám napilno. Začněme v sobotu, co říkáš?"],["다른 데 가요. 여기 안 좋은 것 같아요.","Pojďme jinam. Tady to nevypadá moc dobře."],["일 시작하기 전에 저랑 잠깐 이야기 좀 해요.","Než začnete pracovat, pojďme si na chvilku promluvit."],["네, 지금 해요.","Dobře, promluvme si hned."],["누워요. · 누우시죠. · 눕자. · 누울래요? · 누우실래요?","lehněme si — pět tvarů výzvy (od slovesa 눕다)"],["내일 몇 시에 만날까요? — 세 시에 만나요.","V kolik hodin se zítra sejdeme? — Sejděme se ve tři."],["둘이 뭐 해요? — 같이 공부해요.","Co vy dva děláte? — Učíme se spolu. (běžný přítomný čas)"],["우리 내일부터 같이 운동해요.","Pojďme od zítřka cvičit spolu."],["이거 너무 무거워요. 같이 들어요.","Tohle je moc těžké. Pojďme to zvednout společně."]]}};
Object.assign(MM.mnRoots, {"rae-來":["래","來","přijít"],"il-日":["일","日","den, slunce"]});

